'use strict'

const path = require('path')
const { exec } = require('child_process')
const util = require('util')
const execAsync = util.promisify(exec)
const { parsePomXml } = require('../util/pom')

async function checkProjectType(ctx, cds) {
  const { fs, exists } = cds.utils
  const result = { name: 'project type', passed: true }

  const packageJsonPath = path.join(cds.root, 'package.json')
  const pomPath = path.join(cds.root, 'pom.xml')

  const hasPackageJson = exists(packageJsonPath)
  const hasPom = exists(pomPath)

  if (!hasPackageJson && !hasPom) {
    result.passed = false
    result.message = 'No package.json or pom.xml found. This does not appear to be a CAP project.'
    ctx.project.isNode = false
    ctx.project.isJava = false
    ctx.project.projectTypeMessage = result.message
    return result
  }

  // Check if package.json has CAP Node.js dependencies
  let isNodeCap = false
  if (hasPackageJson) {
    try {
      const pkg = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'))
      const deps = { ...pkg.dependencies, ...pkg.devDependencies }
      isNodeCap = !!deps['@sap/cds'] || !!deps['@sap/cds-dk']

      // For monorepos, also check workspace packages for CAP dependencies
      if (!isNodeCap && pkg.workspaces) {
        const { collectWorkspacePackageJsons } = require('../util/workspaces')
        const wsFiles = await collectWorkspacePackageJsons(cds)
        for (const wsPkgPath of wsFiles) {
          if (wsPkgPath === packageJsonPath) continue
          try {
            const wsPkg = JSON.parse(fs.readFileSync(wsPkgPath, 'utf8'))
            const wsDeps = { ...wsPkg.dependencies, ...wsPkg.devDependencies }
            if (wsDeps['@sap/cds'] || wsDeps['@sap/cds-dk']) { isNodeCap = true; break }
          } catch { /* ignore invalid workspace package.json */ }
        }
      }
    } catch {
      // Ignore invalid package.json
    }
  }

  // Check if pom.xml exists and package.json has CDS dependencies
  // If both exist, it's a Java CAP project (simple heuristic like cds version command)
  // Otherwise, check for com.sap.cds in pom.xml for pure Java projects
  let isJavaCap = false
  if (hasPom) {
    // Simple heuristic: if we have both pom.xml and Node.js CAP dependencies, it's a Java/hybrid project
    // This matches the logic in bin/version.js which treats any project with pom.xml as Java
    if (isNodeCap) {
      isJavaCap = true
    } else {
      // Pure Java project - check for com.sap.cds in pom.xml
      try {
        const pomContent = fs.readFileSync(pomPath, 'utf8')
        // Look for com.sap.cds groupId in dependencies
        isJavaCap = pomContent.includes('<groupId>com.sap.cds</groupId>')

        // If not found in root pom.xml, check if it's a parent POM with modules
        if (!isJavaCap && pomContent.includes('<modules>')) {
          // Check module pom.xml files for com.sap.cds
          try {
            const pom = parsePomXml(pomPath)
            const modules = pom?.modules?.[0]?.module
            if (modules && Array.isArray(modules)) {
              for (const module of modules) {
                const modulePath = path.join(cds.root, module, 'pom.xml')
                if (exists(modulePath)) {
                  const moduleContent = fs.readFileSync(modulePath, 'utf8')
                  if (moduleContent.includes('<groupId>com.sap.cds</groupId>')) {
                    isJavaCap = true
                    break
                  }
                }
              }
            }
          } catch {
            // Ignore errors parsing modules
          }
        }
      } catch {
        // Ignore invalid pom.xml
      }
    }
  }

  // Determine project type based on actual CAP dependencies
  if (!isNodeCap && !isJavaCap) {
    result.passed = false
    result.message = 'No CAP dependencies found. This does not appear to be a CAP project.'
    ctx.project.isNode = false
    ctx.project.isJava = false
    ctx.project.projectTypeMessage = result.message
    return result
  }

  // Detect hybrid projects (both Node.js and Java CAP)
  if (isNodeCap && isJavaCap) {
    result.message = 'Hybrid CAP project (Node.js + Java)'
    ctx.project.isNode = true
    ctx.project.isJava = true

    // Find all package.json files
    ctx.project.packageJsonFiles = await findPackageJsonFiles(cds)
    // Find all pom.xml files
    ctx.project.pomXmlFiles = await findPomXmlFiles(cds)

    if (ctx.project.packageJsonFiles.length > 1 || ctx.project.pomXmlFiles.length > 1) {
      result.message += ` (${ctx.project.packageJsonFiles.length} package.json, ${ctx.project.pomXmlFiles.length} pom.xml files found)`
    }
  } else if (isJavaCap) {
    // Pure Java project
    result.message = 'Java CAP project'
    ctx.project.isNode = false
    ctx.project.isJava = true

    // Find all pom.xml files
    ctx.project.pomXmlFiles = await findPomXmlFiles(cds)

    if (ctx.project.pomXmlFiles.length > 1) {
      result.message += ` (${ctx.project.pomXmlFiles.length} pom.xml files found)`
    }
  } else {
    // Pure Node.js project
    result.message = 'Node.js CAP project'
    ctx.project.isNode = true
    ctx.project.isJava = false

    // Find all non-gitignored package.json files
    ctx.project.packageJsonFiles = await findPackageJsonFiles(cds)

    if (ctx.project.packageJsonFiles.length > 1) {
      result.message += ` (${ctx.project.packageJsonFiles.length} package.json files found)`
    }
  }

  // Store result for later insertion into results array
  ctx.project.projectTypeMessage = result.message

  return result
}

async function findPackageJsonFiles(cds) {
  const { collectWorkspacePackageJsons } = require('../util/workspaces');
  const files = await collectWorkspacePackageJsons(cds);
  const sidecarPath = path.join(cds.root, 'mtx/sidecar/package.json');
  if (cds.utils.exists(sidecarPath) && !files.includes(sidecarPath)) files.push(sidecarPath);

  // Fallback: if root has no workspaces, add non-gitignored subdirectory package.json files
  const rootPkgPath = path.join(cds.root, 'package.json');
  let hasWorkspaces = false;
  if (cds.utils.exists(rootPkgPath)) {
    try {
      const rootPkg = JSON.parse(cds.utils.fs.readFileSync(rootPkgPath, 'utf8'));
      hasWorkspaces = !!rootPkg.workspaces;
    } catch { /* ignore */ }
  }
  if (hasWorkspaces) return files;

  const gitEnv = { ...process.env, GIT_CEILING_DIRECTORIES: path.dirname(cds.root) };
  const entries = cds.utils.fs.readdirSync(cds.root, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.isDirectory() && !entry.name.startsWith('.') && entry.name !== 'node_modules') {
      const subPkgPath = path.join(cds.root, entry.name, 'package.json');
      if (cds.utils.exists(subPkgPath) && !files.includes(subPkgPath)) {
        try {
          await execAsync(`git check-ignore -q "${subPkgPath}"`, { cwd: cds.root, env: gitEnv });
        } catch {
          files.push(subPkgPath);
        }
      }
    }
  }
  return files;
}

async function findPomXmlFiles(cds) {
  const { fs, exists } = cds.utils
  const files = []
  const gitEnv = { ...process.env, GIT_CEILING_DIRECTORIES: path.dirname(cds.root) }

  // Check root pom.xml
  const rootPom = path.join(cds.root, 'pom.xml')
  if (exists(rootPom)) {
    files.push(rootPom)
  }

  // Find subdirectory pom.xml files
  const entries = fs.readdirSync(cds.root, { withFileTypes: true })
  for (const entry of entries) {
    if (entry.isDirectory() && !entry.name.startsWith('.') && entry.name !== 'node_modules' && entry.name !== 'target') {
      const subPomPath = path.join(cds.root, entry.name, 'pom.xml')
      if (exists(subPomPath)) {
        // Check if gitignored
        try {
          await execAsync(`git check-ignore -q "${subPomPath}"`, { cwd: cds.root, env: gitEnv })
          // If no error, file is ignored - skip it
        } catch {
          // File is not ignored, add it
          files.push(subPomPath)
        }
      }
    }
  }

  return files
}

module.exports = {
  checkProjectType,
  findPackageJsonFiles,
  findPomXmlFiles,
}
